import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/** Sends the day the screen shows the sheet as of with every sheet request: a read is answered as
 *  the sheet stood then, and a change is refused. */
export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
  const asOf = inject(Session).asOf();
  if (asOf === null || !req.url.startsWith('/api/sheets/')) return next(req);
  return next(req.clone({ setHeaders: { 'X-As-Of': asOf } }));
};
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** A holiday of the sheet: its day (yyyy-mm-dd). */
export interface Holiday {
  id: number;
  date: string;
}

// The holidays of the active sheet: a claim's due-by fixed at its creation is moved past them.
@Injectable({ providedIn: 'root' })
export class Holidays {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The holidays of the sheet, earliest first. */
  list(sheetId: string): Promise<Holiday[]> {
    return firstValueFrom(this.http.get<Holiday[]>(this.url(sheetId)));
  }

  /** Add a day to the sheet's holidays; refused (409) for a day already on the list. */
  add(date: string): Promise<Holiday> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(this.http.post<Holiday>(this.url(sheetId), { date }, { headers: { 'X-User': user } }));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/holidays`;
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Holiday, Holidays } from '../../core/holidays';
import { Session } from '../../core/session';

const DAY = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's holidays and the entry a day is added with. A claim's terms count business days,
// skipping every Saturday, Sunday and holiday; a holiday added later leaves due-by dates as they are.
@Component({
  selector: 'app-holiday-form',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="holidays-heading">
      <h3 id="holidays-heading">Holidays</h3>
      <form data-testid="holiday-form" [formGroup]="form" (ngSubmit)="submit()">
        <label for="holiday-date">Holiday</label>
        <input id="holiday-date" type="date" data-testid="holiday-date" formControlName="date" />
        <button type="submit" data-testid="holiday-add">Add holiday</button>
        @if (error()) {
          <p role="alert" data-testid="holiday-error">{{ error() }}</p>
        }
      </form>
      <ul data-testid="holidays">
        @for (h of holidays(); track h.id) {
          <li [attr.data-testid]="'holiday-row-' + h.date">{{ h.date }}</li>
        }
      </ul>
    </section>
  `,
})
export class HolidayForm {
  private readonly api = inject(Holidays);
  private readonly session = inject(Session);

  protected readonly holidays = signal<Holiday[]>([]);
  protected readonly error = signal('');
  protected readonly form = new FormGroup({
    date: new FormControl('', { nonNullable: true }),
  });
  private submitting = false;
  private reads = 0;

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    effect(() => {
      this.session.loads();
      const sheetId = this.session.sheetId();
      this.holidays.set([]);
      if (sheetId) void this.reload(sheetId);
    });
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const { date } = this.form.getRawValue();
    if (!DAY.test(date)) {
      this.error.set('Enter the day as yyyy-mm-dd.');
      return;
    }
    if (this.holidays().some((h) => h.date === date)) {
      this.error.set('That day is already a holiday.');
      return;
    }
    this.submitting = true;
    try {
      const saved = await this.api.add(date);
      this.holidays.update((hs) => [...hs.filter((h) => h.id !== saved.id), saved].sort((a, b) => a.date.localeCompare(b.date)));
      this.form.reset({ date: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 409
          ? 'That day is already a holiday, or the sheet may not be changed.'
          : e instanceof HttpErrorResponse && e.status === 403
            ? 'A viewer may not add a holiday.'
            : 'The holiday could not be added.',
      );
    } finally {
      this.submitting = false;
    }
  }

  private async reload(sheetId: string): Promise<void> {
    const read = ++this.reads;
    try {
      const holidays = await this.api.list(sheetId);
      if (read === this.reads) this.holidays.set(holidays);
    } catch {
      // the list stays empty; the next load reads it again
    }
  }
}
